"""Evaluate whether declared source dependencies have changed."""

import json


_MISSING = {"kind": "missing"}


def _canonical_json(value):
    """Return a deterministic representation that preserves JSON value types."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request, policy):
    """Return review status and changed declared paths for request."""
    declared = request.get("declared", [])
    ignored = set(policy.get("ignored", []))
    saved = request.get("saved", {})
    current = request.get("current", {})

    changed = []
    for path in set(declared) - ignored:
        saved_state = saved.get(path, _MISSING)
        current_state = current.get(path, _MISSING)
        if _canonical_json(saved_state) != _canonical_json(current_state):
            changed.append(path)

    changed.sort()
    return {"needs_review": bool(changed), "changed": changed}
